seq = ''
for line in open('region.fasta'):
    if not line.startswith('>'): seq += line.strip().upper()
comp = str.maketrans('ACGT','TGCA')
rc = seq.translate(comp)[::-1]
def orfs(s, min_aa=50):
    res=[]
    for frame in range(3):
        i=frame
        start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod=='ATG' and start is None: start=i
            if cod in ('TAA','TAG','TGA'):
                if start is not None and (i+3-start)>=min_aa*3:
                    res.append((start,i+3,(i+3-start)//3))
                start=None
            i+=3
        if start is not None:
            res.append((start,len(s),None))
    return res
for name,s in (('plus',seq),('minus',rc)):
    print(name)
    for a,b,c in sorted(orfs(s)):
        print('  %d-%d len_nt=%d aa=%s' % (a+1,b,b-a,c))
