# homopolymers >=6, purine/pyrimidine runs, tandem repeats small
import re
print("homopolymer runs >=6:")
for m in re.finditer(r'(A{6,}|T{6,}|G{6,}|C{6,})', seq):
    print('  %d-%d %s' % (m.start()+1, m.end(), m.group()))
print("\ndi/tri-nucleotide tandem repeats (>=5 copies of unit):")
for period in (2,3,4):
    for i in range(n-period*5):
        unit=seq[i:i+period]
        c=0
        while seq[i+c*period:i+(c+1)*period]==unit: c+=1
        if c>=5 and len(set(unit))>1:
            print('  %d-%d unit %s x%d' % (i+1, i+c*period, unit, c))
print("\nG-quadruplex candidates (G3+N1-7 x4):")
for m in re.finditer(r'(?=(G{3,}\w{1,7}G{3,}\w{1,7}G{3,}\w{1,7}G{3,}))', seq):
